	["Threat Line"] = "Linha de ameaça", -- draft
	["In group fights, a thin line on an enemy's bar showing how close it is to turning on you. For tanks, it turns red when you lose a mob."] = "Em lutas em grupo, uma linha fina na barra de um inimigo que mostra o quanto ele está perto de se virar contra você. Para tanques, fica vermelha quando você perde um monstro.", -- draft
	["Combo Points"] = "Pontos de combo", -- draft
