	-- PlateImpact
	["Impact Effects"] = "Efeitos de impacto", -- draft
	["Your target's nameplate reacts to the fight: hits flash, crits glow, interrupted casts shatter."] = "A placa de identificação do seu alvo reage à luta: golpes piscam, críticos brilham, lançamentos interrompidos se despedaçam.", -- draft
	["Every hit lands on the plate, not only in a number."] = "Cada golpe acerta a placa, não só um número.", -- draft
	["Hit Flash"] = "Pisca do golpe", -- draft
	["Your target's bar flashes when it is hit; gold for a critical hit."] = "A barra do seu alvo pisca ao ser atingida; dourada num crítico.", -- draft
	["Damage Chunk"] = "Pedaço de dano", -- draft
	["The part of the bar a hit took stays lit for a moment before it drains, so you see each hit's size."] = "A parte da barra que um golpe levou fica acesa por um momento antes de esvaziar, para você ver o tamanho de cada golpe.", -- draft
	["Crit Glow"] = "Brilho crítico", -- draft
	["A gold glow bursts around your target's bar on a critical hit."] = "Um brilho dourado explode em volta da barra do seu alvo num crítico.", -- draft
	["Kill Flash"] = "Pisca fatal", -- draft
