	["Dodge And Miss"] = "Esquiva e erro", -- draft
	["Dodge, parry and miss words flick off the side of your target's plate."] = "Esquiva, aparo e erro saltam da lateral da placa do seu alvo.", -- draft
	["Cast Warning"] = "Alerta de lançamento", -- draft
	["Your target's cast bar glows hotter near the end, and shatters when interrupted."] = "A barra de lançamento do seu alvo esquenta perto do fim e se despedaça se interrompida.", -- draft
	["On Your Target Frame"] = "No seu quadro de alvo", -- draft
	["Your target frame's health bar shows the same hit effects."] = "A barra de vida do seu quadro de alvo mostra os mesmos efeitos de golpe.", -- draft
	-- Tooltip
	["Tooltip"] = "Dica", -- draft
