	["Background"] = "Fundo", -- draft
	["The tooltips' background: Dark, the game's own, or (with Oldschool) Painted or Parchment."] = "O fundo das dicas: Escuro, o do jogo ou (com Oldschool) Pintado ou Pergaminho.", -- draft
