	["Debuff Glow"] = "Brilho de penalidade", -- draft
	["A glow in the debuff's colour around a friend's frame while they have a debuff that can be removed."] = "Um brilho na cor da penalidade em volta do quadro de um aliado enquanto ele tem uma penalidade removível.", -- draft
	["Debuff Glow Shows"] = "O brilho de penalidade mostra", -- draft
